const input = $('Formular Aufraeumen').first().json;
const serial = String(input['Seriennummer (leer = alle iPads)'] || '').trim();
if (serial.length > 40 || !/^[A-Za-z0-9]*$/.test(serial)) {
  return [{ json: { ok: false, mode: 'manual', title: 'Nichts gestartet', message: 'Die Seriennummer darf nur Buchstaben und Ziffern enthalten.' } }];
}
return [{ json: { ok: true, mode: 'manual', serial } }];

const input = $input.first().json;
const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  serial: input.serial
};
return [{ json: cfg }];

const crypto = require('crypto');
const head = '<?xml version="1.0" encoding="UTF-8"?>\n'
  + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
  + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n';
const tail = (commandUuid) => '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + commandUuid + '</string>\n</dict>\n</plist>\n';
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const cfg = $('Konfiguration').first().json;
const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (devices.length === 0) {
  const message = cfg.serial
    ? 'Es gibt kein angemeldetes iPad mit der Seriennummer ' + cfg.serial + '.'
    : 'Es ist noch kein iPad angemeldet.';
  return [{ json: { skip: true, message } }];
}
return devices.map((device) => {
  const commandUuid = crypto.randomUUID();
  const plist = head
    + '\t\t<key>ManagedAppsOnly</key>\n\t\t<false/>\n'
    + '\t\t<key>RequestType</key>\n\t\t<string>InstalledApplicationList</string>\n'
    + tail(commandUuid);
  return { json: { skip: false, enrollment_id: device.enrollment_id, serial_number: device.serial_number, command_uuid: commandUuid, plist } };
});

const sent = $('Inventurbefehle bauen').all().map((item) => item.json);
const queued = [];
const failed = [];
$input.all().forEach((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  if (body.command_uuid === source.command_uuid) {
    queued.push({ id: source.enrollment_id, uuid: source.command_uuid, serial: source.serial_number });
  } else {
    failed.push({ serial: source.serial_number || source.enrollment_id, detail: String(response.json.statusCode || response.json.error || 'keine Antwort') });
  }
});
return [{ json: { ids: queued.map((q) => q.id).join(','), uuids: queued.map((q) => q.uuid).join(','), queued, failed } }];

const first = $input.first().json;
if (first.ok === false) return [{ json: { title: first.title, message: first.message } }];
const built = $('Inventurbefehle bauen').first().json;
if (built.skip === true) return [{ json: { title: 'Nichts zu tun', message: built.message } }];
const result = $('Inventur auswerten').first().json;
const lines = [];
if (result.queued.length > 0) {
  lines.push('Inventur angefordert bei: ' + result.queued.map((q) => q.serial || q.id).join(', ') + '.');
  lines.push('Sobald ein iPad antwortet, werden alle Apps ausserhalb der Erlaubt-Liste entfernt. Das Ergebnis kommt per ntfy (Home-Lab-MDM).');
}
if (result.failed.length > 0) lines.push('Nicht eingereiht: ' + result.failed.map((f) => f.serial + ' (' + f.detail + ')').join(', ') + '.');
return [{ json: { title: result.failed.length > 0 ? 'Aufraeumen mit Problemen gestartet' : 'Aufraeumen gestartet', message: lines.join(' ') } }];
